"""Core service surface for PrivaCare.

Later work adds the real capabilities described in README.md behind this
module; keep the public surface here backward compatible.
"""

from __future__ import annotations

from typing import Any

from . import __version__
from .access import access_evaluate_request
from .aggregate import aggregate_query_request
from .audit import audit_chain_request, audit_verify_request
from .classifier import classify_request
from .compliance import transfer_evaluate_request
from .consent import consent_evaluate_request, consent_timeline_request
from .deidentifier import deidentify_request
from .differential import differential_aggregate_request
from .encryption import decrypt_request, encrypt_request, rotate_request
from .federated import federated_aggregate_request
from .lineage import trace_lineage_request
from .pseudonymizer import pseudonymize_request
from .risk import reidentification_risk_request
from .subject import process_subject_requests


class Service:
    """Health reporting, classification, de-identification, risk, consent."""

    name = "privacare"
    version = __version__

    def health(self) -> dict[str, str]:
        return {"status": "ok", "service": self.name, "version": self.version}

    def classify(self, payload: Any) -> list[dict]:
        """Classify sensitive fields in a /v1/classify request payload."""
        return classify_request(payload)

    def deidentify(self, payload: Any) -> list[dict]:
        """De-identify records in a /v1/deidentify request payload."""
        return deidentify_request(payload)

    def pseudonymize(self, payload: Any) -> list[dict]:
        """Pseudonymize records in a /v1/pseudonymize request payload."""
        return pseudonymize_request(payload)

    def reidentification_risk(self, payload: Any) -> dict:
        """Measure k-anonymity re-identification risk in a request payload."""
        return reidentification_risk_request(payload)

    def evaluate_consent(self, payload: Any) -> list[dict]:
        """Evaluate accesses against consents in a /v1/consent/evaluate payload."""
        return consent_evaluate_request(payload)

    def consent_timeline(self, payload: Any) -> list[dict]:
        """Rebuild consent lifecycle states for a /v1/consent/timeline payload."""
        return consent_timeline_request(payload)

    def evaluate_access(self, payload: Any) -> list[dict]:
        """Evaluate accesses against grants in a /v1/access/evaluate payload."""
        return access_evaluate_request(payload)

    def audit_chain(self, payload: Any) -> dict:
        """Build a tamper-evident evidence chain for a /v1/audit/chain payload."""
        return audit_chain_request(payload)

    def audit_verify(self, payload: Any) -> dict:
        """Recompute and check an evidence chain for a /v1/audit/verify payload."""
        return audit_verify_request(payload)

    def trace_lineage(self, payload: Any) -> dict:
        """Trace upstream/downstream dataset lineage for a /v1/lineage/trace payload."""
        return trace_lineage_request(payload)

    def encrypt(self, payload: Any) -> list[dict]:
        """Encrypt record fields for a /v1/encryption/encrypt payload."""
        return encrypt_request(payload)

    def decrypt(self, payload: Any) -> list[dict]:
        """Decrypt record envelopes for a /v1/encryption/decrypt payload."""
        return decrypt_request(payload)

    def rotate_encryption(self, payload: Any) -> list[dict]:
        """Re-encrypt record envelopes for a /v1/encryption/rotate payload."""
        return rotate_request(payload)

    def aggregate_query(self, payload: Any) -> dict:
        """Run a small-group protected /v1/query/aggregate payload."""
        return aggregate_query_request(payload)

    def differential_aggregate(self, payload: Any) -> dict:
        """Release a /v1/query/differential-aggregate payload with DP noise."""
        return differential_aggregate_request(payload)

    def evaluate_transfer(self, payload: Any) -> list[dict]:
        """Evaluate transfers against rules in a /v1/compliance/transfer/evaluate payload."""
        return transfer_evaluate_request(payload)

    def process_subject_requests(self, payload: Any) -> dict:
        """Apply export/correct/delete requests in a /v1/subject-requests/process payload."""
        return process_subject_requests(payload)

    def federated_aggregate(self, payload: Any) -> dict:
        """Clip and average federated updates in a /v1/federated/aggregate payload."""
        return federated_aggregate_request(payload)

"""K-anonymity based re-identification risk measurement.

Pure and request-scoped, like the classifier and de-identifier: the
payload is only read, never mutated, and nothing is retained between
requests. Equivalence classes come from the ordered combination of the
scalar values at the caller-supplied quasi-identifier JSON Pointers.
"""

from __future__ import annotations

from decimal import Decimal, ROUND_HALF_UP
from typing import Any

from .classifier import (
    InvalidRequest,
    InvalidSchema,
    _parse_pointer,
    _validate_records,
)

_QUANTUM = Decimal("0.000001")


class InvalidQuasiIdentifiers(ValueError):
    """The quasi_identifiers array is malformed or does not resolve to scalars."""


class InvalidK(ValueError):
    """k is not a JSON integer no less than 2."""


def _round6(value: Decimal) -> float:
    """Round a decimal to six places, half up, and emit as a JSON number."""
    return float(value.quantize(_QUANTUM, rounding=ROUND_HALF_UP))


def _validate_quasi_identifiers(raw: Any) -> list[tuple[str, ...]]:
    if not isinstance(raw, list) or not raw:
        raise InvalidQuasiIdentifiers("quasi_identifiers must be a non-empty array")
    pointers: list[tuple[str, ...]] = []
    seen: set[str] = set()
    for item in raw:
        if not isinstance(item, str):
            raise InvalidQuasiIdentifiers("quasi_identifiers must be JSON Pointer strings")
        try:
            segments = _parse_pointer(item)
        except InvalidSchema as exc:
            raise InvalidQuasiIdentifiers(str(exc)) from exc
        if item in seen:
            raise InvalidQuasiIdentifiers("quasi_identifiers must not contain duplicates")
        seen.add(item)
        pointers.append(segments)
    return pointers


def _validate_k(raw: Any) -> int:
    # bool is an int subclass in Python, but JSON true/false is not a number.
    if isinstance(raw, bool) or not isinstance(raw, int) or raw < 2:
        raise InvalidK("k must be a JSON integer no less than 2")
    return raw


def _scalar_key(value: Any) -> tuple[int, Any]:
    """Build a hashable group key with JSON equality semantics.

    Tags keep the JSON types apart (true != 1, null != false) while ints
    and floats share a numeric tag keyed by their exact decimal value so
    that 1 and 1.0 land in the same equivalence class.
    """
    if value is None:
        return (0, 0)
    if isinstance(value, bool):
        return (1, value)
    if isinstance(value, int):
        return (2, Decimal(value))
    if isinstance(value, float):
        return (2, Decimal(str(value)))
    if isinstance(value, str):
        return (3, value)
    raise InvalidQuasiIdentifiers("each quasi-identifier pointer must resolve to a scalar")


def _resolve_scalar(record: dict, segments: tuple[str, ...]) -> Any:
    """Resolve a JSON Pointer, requiring the target to be a scalar.

    Array index handling follows RFC 6901: "0" alone may have a leading
    zero, every other index may not, and "-" never resolves.
    """
    node: Any = record
    for segment in segments:
        if isinstance(node, dict):
            if segment not in node:
                raise InvalidQuasiIdentifiers(
                    "every quasi-identifier pointer must resolve on every record"
                )
            node = node[segment]
        elif isinstance(node, list):
            if segment == "-" or not segment.isdigit():
                raise InvalidQuasiIdentifiers("invalid array index in quasi-identifier pointer")
            if segment != "0" and segment[0] == "0":
                raise InvalidQuasiIdentifiers("array indices must not have leading zeros")
            index = int(segment)
            if index >= len(node):
                raise InvalidQuasiIdentifiers(
                    "every quasi-identifier pointer must resolve on every record"
                )
            node = node[index]
        else:
            raise InvalidQuasiIdentifiers(
                "every quasi-identifier pointer must resolve on every record"
            )
    if isinstance(node, (dict, list)):
        raise InvalidQuasiIdentifiers("quasi-identifier pointers must resolve to scalar values")
    return node


def _row_key(record: dict, pointers: list[tuple[str, ...]]) -> tuple[tuple[int, Any], ...]:
    return tuple(_scalar_key(_resolve_scalar(record, segments)) for segments in pointers)


def reidentification_risk_request(payload: Any) -> dict:
    """Validate a /v1/reidentification-risk payload and score every record."""
    records = _validate_records(payload)
    pointers = _validate_quasi_identifiers(payload.get("quasi_identifiers"))
    k = _validate_k(payload.get("k"))

    row_keys = [_row_key(record, pointers) for record in records]
    class_sizes: dict[tuple, int] = {}
    for row_key in row_keys:
        class_sizes[row_key] = class_sizes.get(row_key, 0) + 1

    results: list[dict] = []
    at_risk_records = 0
    for index, row_key in enumerate(row_keys):
        class_size = class_sizes[row_key]
        at_risk = class_size < k
        if at_risk:
            at_risk_records += 1
        results.append(
            {
                "index": index,
                "class_size": class_size,
                "risk_score": _round6(Decimal(1) / Decimal(class_size)),
                "at_risk": at_risk,
            }
        )

    record_count = len(records)
    summary = {
        "k": k,
        "record_count": record_count,
        "equivalence_class_count": len(class_sizes),
        "minimum_class_size": min(class_sizes.values()),
        "at_risk_records": at_risk_records,
        "at_risk_rate": _round6(Decimal(at_risk_records) / Decimal(record_count)),
    }
    return {"summary": summary, "results": results}

"""Small-group protected aggregate queries.

Pure and request-scoped like the other capabilities: records are only
read from the current payload, the caller's data is never mutated and
nothing is retained between requests. Records are partitioned by the
ordered scalar values found at the ``group_by`` JSON Pointers, and only
groups whose size reaches ``minimum_group_size`` are returned; smaller
groups are suppressed wholesale so their keys, sizes, metrics and
values never leave the process.
"""

from __future__ import annotations

import math
from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import Any

from .classifier import (
    InvalidRequest,
    InvalidSchema,
    _parse_pointer as _parse_json_pointer,
    _validate_records,
)

_QUANTUM = Decimal("0.000001")

_OPERATIONS = frozenset(("count", "sum", "average"))


class InvalidGroupBy(ValueError):
    """group_by is malformed or does not resolve to scalar values."""


class InvalidMetric(ValueError):
    """A metric definition is malformed or its field is not finite numeric."""


class InvalidThreshold(ValueError):
    """minimum_group_size is not a JSON integer in [2, 1000]."""


def _round6(value: Decimal) -> float:
    """Round a decimal to six places, half up, and emit as a JSON number."""
    return float(value.quantize(_QUANTUM, rounding=ROUND_HALF_UP))


def _parse_pointer(raw: str, error: type[ValueError]) -> tuple[str, ...]:
    try:
        return _parse_json_pointer(raw)
    except InvalidSchema as exc:
        raise error(str(exc)) from exc


def _resolve(record: dict, segments: tuple[str, ...], error: type[ValueError]) -> Any:
    """Resolve a JSON Pointer with strict RFC 6901 array index handling."""
    node: Any = record
    for segment in segments:
        if isinstance(node, dict):
            if segment not in node:
                raise error("every pointer must resolve on every record")
            node = node[segment]
        elif isinstance(node, list):
            if segment == "-" or not segment.isdigit():
                raise error("invalid array index in pointer")
            if segment != "0" and segment[0] == "0":
                raise error("array indices must not have leading zeros")
            index = int(segment)
            if index >= len(node):
                raise error("every pointer must resolve on every record")
            node = node[index]
        else:
            raise error("every pointer must resolve on every record")
    return node


def _group_signature_value(value: Any) -> tuple[int, Any]:
    """Tag a resolved group-by value with JSON equality semantics.

    Types never compare across tags (null != false != 0, strings stay
    distinct) while ints and floats share the numeric tag keyed by their
    decimal value so 1 and 1.0 land in the same group.
    """
    if value is None:
        return (0, 0)
    if isinstance(value, bool):
        return (1, value)
    if isinstance(value, int):
        return (2, Decimal(value))
    if isinstance(value, float):
        if not math.isfinite(value):
            raise InvalidGroupBy("group_by values must be finite scalars")
        return (2, Decimal(str(value)))
    if isinstance(value, str):
        return (3, value)
    raise InvalidGroupBy("group_by pointers must resolve to scalar values")


def _require_finite_number(value: Any) -> None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise InvalidMetric("metric fields must be finite JSON numbers on every record")
    if isinstance(value, float) and not math.isfinite(value):
        raise InvalidMetric("metric fields must be finite JSON numbers on every record")


def _decimal_number(value: Any) -> Decimal:
    if isinstance(value, int):
        return Decimal(value)
    return Decimal(str(value))


def _validate_group_by(raw: Any, records: list[dict]) -> list[tuple[str, ...]]:
    if not isinstance(raw, list):
        raise InvalidGroupBy("group_by must be an array of JSON Pointer strings")
    pointers: list[tuple[str, ...]] = []
    seen: set[str] = set()
    for item in raw:
        if not isinstance(item, str):
            raise InvalidGroupBy("group_by entries must be JSON Pointer strings")
        if item in seen:
            raise InvalidGroupBy("group_by must not contain duplicates")
        seen.add(item)
        pointers.append(_parse_pointer(item, InvalidGroupBy))
    # Every non-empty pointer must resolve to an allowed scalar on every
    # record; the root pointer resolves to the record container and fails.
    for record in records:
        for segments in pointers:
            value = _resolve(record, segments, InvalidGroupBy)
            _group_signature_value(value)
    return pointers


def _validate_metrics(raw: Any, records: list[dict]) -> list[tuple[str, str, tuple[str, ...] | None]]:
    if not isinstance(raw, list) or not raw:
        raise InvalidMetric("metrics must be a non-empty array")
    metrics: list[tuple[str, str, tuple[str, ...] | None]] = []
    names: set[str] = set()
    for item in raw:
        if not isinstance(item, dict):
            raise InvalidMetric("each metric must be an object")
        name = item.get("name")
        if not isinstance(name, str) or not name:
            raise InvalidMetric("each metric needs a unique non-empty name")
        if name in names:
            raise InvalidMetric("metric names must be unique")
        names.add(name)
        operation = item.get("operation")
        if not isinstance(operation, str) or operation not in _OPERATIONS:
            raise InvalidMetric("operation must be count, sum or average")
        if operation == "count":
            if "field" in item:
                raise InvalidMetric("count metrics must not carry a field")
            metrics.append((name, operation, None))
            continue
        field = item.get("field")
        if not isinstance(field, str) or not field or not field.startswith("/"):
            raise InvalidMetric(
                "sum and average metrics require a non-root JSON Pointer field"
            )
        segments = _parse_pointer(field, InvalidMetric)
        if not segments:
            raise InvalidMetric(
                "sum and average metrics require a non-root JSON Pointer field"
            )
        for record in records:
            _require_finite_number(_resolve(record, segments, InvalidMetric))
        metrics.append((name, operation, segments))
    return metrics


def _validate_threshold(raw: Any) -> int:
    # bool is an int subclass in Python, but JSON true/false is not a number.
    if isinstance(raw, bool) or not isinstance(raw, int) or not 2 <= raw <= 1000:
        raise InvalidThreshold("minimum_group_size must be a JSON integer between 2 and 1000")
    return raw


def aggregate_query_request(payload: Any) -> dict:
    """Validate a /v1/query/aggregate payload and run the grouped statistics."""
    records = _validate_records(payload)
    group_pointers = _validate_group_by(payload.get("group_by"), records)
    metrics = _validate_metrics(payload.get("metrics"), records)
    threshold = _validate_threshold(payload.get("minimum_group_size"))

    # Accumulate in first-appearance order; signatures carry JSON equality.
    order: list[tuple[tuple[int, Any], ...]] = []
    groups: dict[tuple, dict[str, Any]] = {}
    with localcontext() as context:
        context.prec = 60
        for record in records:
            values = [_resolve(record, segments, InvalidGroupBy) for segments in group_pointers]
            signature = tuple(_group_signature_value(value) for value in values)
            entry = groups.get(signature)
            if entry is None:
                entry = {
                    "key": values,
                    "size": 0,
                    "sums": [Decimal(0) for _ in metrics],
                }
                groups[signature] = entry
                order.append(signature)
            entry["size"] += 1
            for index, (_name, operation, segments) in enumerate(metrics):
                if segments is not None:
                    value = _resolve(record, segments, InvalidMetric)
                    entry["sums"][index] += _decimal_number(value)

        visible_groups: list[dict] = []
        suppressed_group_count = 0
        for signature in order:
            entry = groups[signature]
            size = entry["size"]
            if size < threshold:
                # Nothing about a suppressed group is exposed.
                suppressed_group_count += 1
                continue
            metric_values: dict[str, Any] = {}
            for index, (name, operation, _segments) in enumerate(metrics):
                if operation == "count":
                    metric_values[name] = size
                elif operation == "sum":
                    metric_values[name] = _round6(entry["sums"][index])
                else:
                    metric_values[name] = _round6(entry["sums"][index] / Decimal(size))
            visible_groups.append(
                {"key": entry["key"], "size": size, "metrics": metric_values}
            )

    return {"groups": visible_groups, "suppressed_group_count": suppressed_group_count}

